      var at = typeof j.mint === 'string' ? canonicalMint(j.mint) : '';
      if (!at || at !== mintOf(wallet)) return false;
      var key = (typeof j.changeTo === 'string' && /^0[23][0-9a-f]{64}$/i.test(j.changeTo)) ? j.changeTo.toLowerCase() : '';
