          if (split.handedOn && split.handedOn.length) {
            rememberHandedOn(split.handedOn);
            takeFromUnclaimed(split.handedOn);
            console.log('[foxy] handed on ' + said(sumProofs(split.handedOn)) + ' of locked ecash, signed here');
          }
